import React, { useEffect, useRef } from 'react';
import { Box, Typography, Paper, CircularProgress } from '@mui/material';
import { MapPanel as MapPanelType } from '@/types/StoryConfig';
import '@/types/GeoView'; // Import GeoView global types

// Extend Window interface to track which maps are initializing
declare global {
  interface Window {
    _cgpvInitializing?: Set<string>;
  }
}

// Initialize global tracking set
if (typeof window !== 'undefined' && !window._cgpvInitializing) {
  window._cgpvInitializing = new Set();
}

interface MapPanelProps {
  panel: MapPanelType;
  panelInstanceId?: string;
}

export const MapPanel: React.FC<MapPanelProps> = ({ panel, panelInstanceId }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);
  const [showScrollGuard, setShowScrollGuard] = React.useState(false);
  
  // Use panel instance ID plus config to avoid collisions when multiple panels share a config.
  const mapId = useRef(
    `map-${(panelInstanceId || 'panel').replace(/[^a-zA-Z0-9]/g, '-')}-${panel.config.replace(/[^a-zA-Z0-9]/g, '-')}`
  );
  const initStartedRef = useRef(false);  // Track if init actually got past abort check
  const mountedRef = useRef(true);
  const unsubscribeRef = useRef<(() => void) | null>(null);
  const scrollGuardTimeoutRef = useRef<number | null>(null);

  useEffect(() => {
    mountedRef.current = true;
    
    const initMap = async () => {
      if (!window.cgpv) {
        if (mountedRef.current) {
          setTimeout(initMap, 500);
        }
        return;
      }

      if (!mapContainerRef.current) {
        return;
      }

      try {
        // Load and set up the map configuration
        const configPath = panel.config === 'default' || panel.config === '' 
          ? 'configs/default-map.json' 
          : panel.config;

        const response = await fetch(configPath);
        if (!response.ok) {
          throw new Error(`Failed to load map config: HTTP ${response.status}`);
        }
        const mapConfig = await response.json();

        // Set DOM attributes for GeoView to find
        mapContainerRef.current.setAttribute('id', mapId.current);
        mapContainerRef.current.setAttribute('data-config', JSON.stringify(mapConfig));
        mapContainerRef.current.setAttribute('data-lang', 'en');
        mapContainerRef.current.classList.add('geoview-map');

        // Register onMapReady listener - fires when THIS map is ready
        unsubscribeRef.current = window.cgpv.onMapReady((mapViewer) => {
          if (mapViewer.mapId === mapId.current && mountedRef.current) {
            mapContainerRef.current?.classList.add('geoview-loaded');
            setLoading(false);
            initStartedRef.current = true;
          }
        });

        // If map already registered (another mount beat us), onMapReady will still fire
        if (!window.cgpv.api.hasMapViewer(mapId.current)) {
          // Check if another mount is already initializing this map
          if (!window._cgpvInitializing?.has(mapId.current)) {
            // Mark this map as initializing to prevent concurrent init calls
            window._cgpvInitializing?.add(mapId.current);
            
            // Trigger init to scan DOM for uninitialized map elements
            window.cgpv.init();
            
            // Remove from initializing set after a short delay to allow GeoView to complete
            setTimeout(() => {
              window._cgpvInitializing?.delete(mapId.current);
            }, 100);
          }
        }

      } catch (err) {
        if (mountedRef.current) {
          console.error('[Map] Initialization error:', err);
          setError('Failed to initialize map');
          setLoading(false);
        }
      }
    };

    initMap();

    return () => {
      mountedRef.current = false;
      
      if (unsubscribeRef.current) {
        unsubscribeRef.current();
        unsubscribeRef.current = null;
      }
      
      if (mapContainerRef.current) {
        mapContainerRef.current.removeAttribute('id');
        mapContainerRef.current.removeAttribute('data-config');
        mapContainerRef.current.removeAttribute('data-lang');
        mapContainerRef.current.classList.remove('geoview-map', 'geoview-loaded');
      }
      
      if (initStartedRef.current) {
        (async () => {
          try {
            const mapViewer = window.cgpv?.api?.getMapViewer(mapId.current);
            if (mapViewer && window.cgpv?.api?.deleteMapViewer) {
              await window.cgpv.api.deleteMapViewer(mapId.current, true);
            }
          } catch (err) {
            // Silently ignore cleanup errors
          }
        })();
      }
    };
  }, [panel.config, panelInstanceId]);

  // Scroll guard to prevent accidental zooming
  useEffect(() => {
    if (!panel.scrollguard || !mapContainerRef.current) return;

    const handleWheel = (e: WheelEvent) => {
      // Allow zoom if Ctrl (Windows/Linux) or Cmd (Mac) is pressed
      if (e.ctrlKey || e.metaKey) {
        setShowScrollGuard(false);
        return;
      }

      // Prevent map zoom
      e.preventDefault();
      e.stopPropagation();
      
      // Show scroll guard overlay
      setShowScrollGuard(true);
      
      // Clear existing timeout
      if (scrollGuardTimeoutRef.current) {
        window.clearTimeout(scrollGuardTimeoutRef.current);
      }
      
      // Hide overlay after 1.5 seconds
      scrollGuardTimeoutRef.current = window.setTimeout(() => {
        setShowScrollGuard(false);
      }, 1500);
    };

    const mapElement = mapContainerRef.current;
    // Use capture phase to intercept before GeoView's handlers
    mapElement.addEventListener('wheel', handleWheel, { passive: false, capture: true });

    return () => {
      mapElement.removeEventListener('wheel', handleWheel, { capture: true });
      if (scrollGuardTimeoutRef.current) {
        window.clearTimeout(scrollGuardTimeoutRef.current);
      }
    };
  }, [panel.scrollguard]);

  if (error) {
    return (
      <Box sx={{ mx: { xs: -2, md: 0 } }}>
        <Paper
          elevation={2}
          sx={{
            overflow: 'hidden',
            borderRadius: { xs: 0, md: 2 },
            backgroundColor: 'error.light',
          }}
        >
          <Box sx={{ p: 4, textAlign: 'center' }}>
            <Typography variant="body1" color="error">
              {error}
            </Typography>
          </Box>
        </Paper>
      </Box>
    );
  }

  return (
    <Box sx={{ mx: { xs: -2, md: 0 } }}>
      <Paper
        elevation={2}
        sx={{
          overflow: 'hidden',
          borderRadius: { xs: 0, md: 2 },
          height: panel.title ? 'auto' : '600px',
        }}
      >
      {panel.title && (
        <Box sx={{ p: 2, borderBottom: '1px solid', borderColor: 'divider' }}>
          <Typography variant="h5" component="h3" sx={{ fontWeight: 600 }}>
            {panel.title}
          </Typography>
        </Box>
      )}
      <Box sx={{ position: 'relative' }}>
        <Box
          ref={mapContainerRef}
          sx={{
            width: '100%',
            height: panel.title ? '500px' : '600px',
            backgroundColor: 'grey.200',
          }}
        />
        {loading && (
          <Box
            sx={{
              position: 'absolute',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              backgroundColor: 'rgba(255, 255, 255, 0.9)',
              zIndex: 1000,
              pointerEvents: 'none',
            }}
          >
            <Box sx={{ textAlign: 'center' }}>
              <CircularProgress />
              <Typography variant="body1" color="text.secondary" sx={{ mt: 2 }}>
                Loading GeoView map...
              </Typography>
            </Box>
          </Box>
        )}
        {/* Scroll guard overlay */}
        {showScrollGuard && panel.scrollguard && (
          <Box
            sx={{
              position: 'absolute',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              backgroundColor: 'rgba(0, 0, 0, 0.5)',
              zIndex: 1001,
              pointerEvents: 'none',
              transition: 'opacity 0.2s',
            }}
          >
            <Box
              sx={{
                backgroundColor: 'rgba(255, 255, 255, 0.95)',
                px: 3,
                py: 2,
                borderRadius: 2,
                boxShadow: 3,
              }}
            >
              <Typography variant="body1" sx={{ fontWeight: 600 }}>
                Use Ctrl + scroll to zoom the map
              </Typography>
            </Box>
          </Box>
        )}
      </Box>
    </Paper>
    </Box>
  );
};
